from pathlib import Path
import re
errors = []
for page in Path('docs').rglob('*.md'):
    content = re.sub(r'`[^`]*`', '', page.read_text())
    for target in re.findall(r'\]\(([^)]+)\)', content):
        if '://' in target:
            continue
        name, _, anchor = target.partition('#')
        path = page.parent / name if name else page
        if not path.is_file():
            errors.append(f'{page}: {target}')
        elif anchor and path.suffix == '.md':
            headings = re.findall(r'^#+ (.+)$', path.read_text(), re.M)
            anchors = [re.sub(r'[^\w -]', '', h.lower()).replace(' ', '-') for h in headings]
            if anchor not in anchors:
                errors.append(f'{page}: missing anchor in {target}')
if errors:
    raise SystemExit('\n'.join(errors))
print('All documentation links and heading anchors resolve (excluding inline code examples).')
